import base64, hashlib, os, stat
from pathlib import Path
os.umask(0o077)
root=Path("/home/qian/hepta-runtime-optimization-20261106-r33")
assert root.resolve(strict=True)==root and root.stat().st_uid==os.geteuid()
path=root/"archive_r33_qualification_evidence.py"
body=base64.b64decode("",validate=True)
assert len(body)==31940 and hashlib.sha256(body).hexdigest()=="3b150b9cc56bcad3cb170d1612b2cf2c0a5b0b36e875a5b7430607709a5f7954"
assert not os.path.lexists(path)
fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW|os.O_CLOEXEC,0o600)
with os.fdopen(fd,"wb") as stream:
    stream.write(body); stream.flush(); os.fsync(stream.fileno())
info=path.lstat()
assert stat.S_ISREG(info.st_mode) and info.st_nlink==1 and info.st_size==len(body)
assert path.read_bytes()==body
os.execv("/usr/bin/python3",["/usr/bin/python3","-B",str(path),"--kind","qualification"])
